  function pair4() { var a, b, r; do { a = pad(rnd(1, 14).toString(2), 4); b = pad(rnd(1, 14).toString(2), 4); r = add(a, b); } while (r.out || r.count < 1 || a === b); return { a: a, b: b, r: r }; }
